CREATE TRIGGER IF NOT EXISTS data_apps_cap BEFORE INSERT ON data_apps BEGIN
 SELECT CASE WHEN (SELECT COUNT(*) FROM data_apps WHERE publisher_id=NEW.publisher_id AND state!='deleted')>=3 THEN RAISE(ABORT,'data_apps_quota') END;
END;

CREATE TRIGGER IF NOT EXISTS data_record_owner BEFORE INSERT ON data_records BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM data_apps WHERE id=NEW.app_id AND publisher_id=NEW.publisher_id AND state='active') THEN RAISE(ABORT,'data_app_inactive') END;
END;

CREATE TRIGGER IF NOT EXISTS data_record_insert AFTER INSERT ON data_records BEGIN
 UPDATE data_accounts SET bytes=bytes+NEW.charge,records=records+1 WHERE id=NEW.publisher_id;
 UPDATE data_apps SET bytes=bytes+NEW.charge,records=records+1 WHERE id=NEW.app_id;
 UPDATE data_collections SET records=records+1,change_seq=change_seq+1 WHERE app_id=NEW.app_id AND key=NEW.collection;
END;

CREATE TRIGGER IF NOT EXISTS data_record_update AFTER UPDATE OF data,charge,revision ON data_records BEGIN
 UPDATE data_accounts SET bytes=bytes+NEW.charge-OLD.charge WHERE id=NEW.publisher_id;
 UPDATE data_apps SET bytes=bytes+NEW.charge-OLD.charge WHERE id=NEW.app_id;
 UPDATE data_collections SET change_seq=change_seq+1 WHERE app_id=NEW.app_id AND key=NEW.collection;
END;

CREATE TRIGGER IF NOT EXISTS data_record_delete AFTER DELETE ON data_records BEGIN
 DELETE FROM data_history WHERE record_id=OLD.id;
 UPDATE data_accounts SET bytes=bytes-OLD.charge,records=records-1 WHERE id=OLD.publisher_id;
 UPDATE data_apps SET bytes=bytes-OLD.charge,records=records-1 WHERE id=OLD.app_id;
 UPDATE data_collections SET records=records-1,change_seq=change_seq+1 WHERE app_id=OLD.app_id AND key=OLD.collection;
END;

CREATE TRIGGER IF NOT EXISTS data_history_insert AFTER INSERT ON data_history BEGIN
 UPDATE data_accounts SET bytes=bytes+NEW.charge WHERE id=NEW.publisher_id;
 UPDATE data_apps SET bytes=bytes+NEW.charge WHERE id=NEW.app_id;
END;

CREATE TRIGGER IF NOT EXISTS data_history_delete AFTER DELETE ON data_history BEGIN
 UPDATE data_accounts SET bytes=bytes-OLD.charge WHERE id=OLD.publisher_id;
 UPDATE data_apps SET bytes=bytes-OLD.charge WHERE id=OLD.app_id;
END;

CREATE TRIGGER IF NOT EXISTS data_config_insert AFTER INSERT ON data_apps BEGIN
 UPDATE data_accounts SET bytes=bytes+1024+length(CAST(NEW.active_config AS BLOB))+length(CAST(NEW.pending_config AS BLOB)) WHERE id=NEW.publisher_id;
 UPDATE data_apps SET bytes=bytes+1024+length(CAST(NEW.active_config AS BLOB))+length(CAST(NEW.pending_config AS BLOB)) WHERE id=NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS data_config_update AFTER UPDATE OF active_config,pending_config,state ON data_apps BEGIN
 UPDATE data_accounts SET bytes=bytes+(CASE WHEN NEW.state='deleted' THEN 0 ELSE 1024+length(CAST(NEW.active_config AS BLOB))+length(CAST(NEW.pending_config AS BLOB)) END)-(CASE WHEN OLD.state='deleted' THEN 0 ELSE 1024+length(CAST(OLD.active_config AS BLOB))+length(CAST(OLD.pending_config AS BLOB)) END) WHERE id=NEW.publisher_id;
 UPDATE data_apps SET bytes=bytes+(CASE WHEN NEW.state='deleted' THEN 0 ELSE 1024+length(CAST(NEW.active_config AS BLOB))+length(CAST(NEW.pending_config AS BLOB)) END)-(CASE WHEN OLD.state='deleted' THEN 0 ELSE 1024+length(CAST(OLD.active_config AS BLOB))+length(CAST(OLD.pending_config AS BLOB)) END) WHERE id=NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS data_grants_cap BEFORE INSERT ON data_grants BEGIN
 SELECT CASE WHEN (SELECT COUNT(*) FROM data_grants WHERE app_id=NEW.app_id AND revoked=0 AND expires>unixepoch())>=20 THEN RAISE(ABORT,'data_grants_quota') END;
END;

CREATE TRIGGER IF NOT EXISTS data_credentials_cap BEFORE INSERT ON data_credentials BEGIN
 SELECT CASE WHEN (SELECT COUNT(*) FROM data_credentials WHERE publisher_id=NEW.publisher_id AND revoked=0 AND expires>unixepoch())>=10 THEN RAISE(ABORT,'data_credentials_quota') END;
END;
